#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {
 public class RailConsistMotionTests {
  internal static JObject Profile()=>JObject.Parse(@"{
   'version':'world-boss.rail-geometry.v1.20261002','status':'LOCAL_TEST_PROFILE','geometryRef':'LOCAL_MAINLINE_DETOUR','contentVersion':'LOCAL_GEO','roundId':'p1r1','frame':'PATH_LOCAL_FORWARD_RIGHT_MM',
   'maxVehicles':6,'maxConsistLengthMm':60000,'maxSpeedMmPerSecond':20000,'maxAccelerationMmPerSecondSquared':10000,'maxSampleMs':1000,
   'paths':{'LEFT':{'splitSmm':40000,'mergeSmm':60000,'points':[{'sMm':0,'xMm':-40000,'yMm':0},{'sMm':40000,'xMm':0,'yMm':0},{'sMm':60000,'xMm':20000,'yMm':0},{'sMm':140000,'xMm':100000,'yMm':0}]},
   'RIGHT':{'splitSmm':40000,'mergeSmm':65612,'points':[{'sMm':0,'xMm':-40000,'yMm':0},{'sMm':40000,'xMm':0,'yMm':0},{'sMm':52806,'xMm':10000,'yMm':8000},{'sMm':65612,'xMm':20000,'yMm':0},{'sMm':145612,'xMm':100000,'yMm':0}]}},
   'vehicles':[{'id':'loco','lengthMm':4000,'gapAfterMm':1000,'halfWidthMm':500},{'id':'car','lengthMm':5000,'gapAfterMm':0,'halfWidthMm':500}],
   'attack':{'impactAtMs':15500,'areas':[{'minXmm':0,'maxXmm':18000,'minYmm':-200,'maxYmm':200}]}}");
  static JObject Sample(long speed=10000,long head=10000)=>new JObject{["atMs"]=10000,["sequence"]=0,["headDistanceMm"]=head,["distanceRemainder2000"]=0,["actualMmPerSecond"]=speed,["targetMmPerSecond"]=speed,["forcedSlowdownBps"]=0};
  static RailConsistMotion Create(JObject p=null,JObject first=null)=>new RailConsistMotion(new MainlineDetourPath(p??Profile()),first??Sample(),2000,4000);
  static void LongConsist(JObject p){p["vehicles"]=new JArray(Enumerable.Range(0,6).Select(i=>new JObject{["id"]="v"+i,["lengthMm"]=5000,["gapAfterMm"]=i==5?0:1000,["halfWidthMm"]=500}));}
  [Test] public void WireCompatibleDistanceRemainderSampleMustBeProvided(){Assert.NotNull(typeof(RailConsistMotion).GetMethod("ReadSample"));}
  [Test] public void EntryContinuesMainlineAndRightIsIndependentOfCamera(){var a=Create();var b=Create();b.SelectPath("RIGHT");a.Advance(4500);b.Advance(4500);Assert.AreEqual("ENTRY",a.SelectedPath);Assert.AreEqual(0,a.Occupancy()[0].Front.DriverRightMm);Assert.Greater(b.Occupancy()[0].Front.DriverRightMm,0);Assert.AreEqual(a.HeadFrontArcMm,b.HeadFrontArcMm);}
  [Test] public void TrustedRouteRetryIsIdempotentAndLateChangeIsRejected(){var m=Create();m.SelectPath("RIGHT");var before=m.CaptureLocal();m.SelectPath("RIGHT");Assert.IsTrue(JToken.DeepEquals(before,m.CaptureLocal()));Assert.Throws<InvalidOperationException>(()=>m.SelectPath("LEFT"));Assert.Throws<ArgumentException>(()=>m.SelectPath("ENTRY"));var a=Create();a.Advance(3000);Assert.Throws<InvalidOperationException>(()=>a.SelectPath("RIGHT"));}
  [Test] public void AllCarsFollowSameArcAndGapIsPhysical(){var m=Create();m.SelectPath("RIGHT");m.Advance(5500);var v=m.Occupancy();Assert.AreEqual(2,v.Count);Assert.AreEqual(1000,v[0].RearArcMm-v[1].FrontArcMm);Assert.Greater(v[1].Rear.DriverRightMm,0);Assert.AreEqual(10000,m.ConsistLengthMm);}
  [Test] public void SplitAndTailMergeAreDistinctAndExactBoundaryPermitsNextBranch(){var m=Create();m.SelectPath("RIGHT");m.Advance(3000);CollectionAssert.AreEqual(new[]{"HEAD_SPLIT"},m.ObservedCrossings().Select(e=>(string)e["kind"]));m.Advance(1000);Assert.IsTrue(m.TailPassedSplit);Assert.IsFalse(m.NextBranchPermitted);m.Advance(1500);Assert.IsFalse(m.NextBranchPermitted);m.Advance(1062);Assert.IsTrue(m.NextBranchPermitted);CollectionAssert.AreEqual(new[]{"HEAD_SPLIT","TAIL_SPLIT","TAIL_MERGE"},m.ObservedCrossings().Select(e=>(string)e["kind"]));}
  [Test] public void ConstantIntegerSpeedRetainsSubMillimeterDistanceAcrossPartitions(){var a=Create(first:Sample(1));var b=Create(first:Sample(1));a.Advance(1000);for(int i=0;i<1000;i++)b.Advance(1);Assert.AreEqual(10001,a.HeadFrontArcMm);Assert.AreEqual(a.HeadFrontArcMm,b.HeadFrontArcMm);Assert.AreEqual(a.ReadSample()["distanceRemainder2000"],b.ReadSample()["distanceRemainder2000"]);}
  [Test] public void AccelerationSplitsAtTargetAndEverySampleObeysIntegral(){var m=Create(first:Sample(0));m.SetTargetSpeed(3000);var frames=m.Advance(2000);Assert.AreEqual(3,frames.Count);Assert.AreEqual(11500,(long)frames[1]["atMs"]);Assert.AreEqual(13750,m.HeadFrontArcMm);Assert.AreEqual(3000,m.ActualSpeedMmPerSecond);CheckSamples(Sample(0),new JArray(frames),10000);}
  [Test] public void SlowdownKeepsTargetAndReleaseAcceleratesGradually(){var m=Create();m.SetForcedSlowdown(5000);m.Advance(1000);Assert.AreEqual(6000,m.ActualSpeedMmPerSecond);Assert.AreEqual(10000,m.TargetSpeedMmPerSecond);m.Advance(250);Assert.AreEqual(5000,m.ActualSpeedMmPerSecond);m.SetForcedSlowdown(0);m.Advance(1000);Assert.AreEqual(7000,m.ActualSpeedMmPerSecond);Assert.AreEqual(10000,m.TargetSpeedMmPerSecond);}
  [Test] public void FullSlowdownStopsDistanceButClockAndEventsStayValid(){var m=Create(first:Sample(0));m.SetTargetSpeed(10000);m.SetForcedSlowdown(10000);m.Advance(5000);Assert.AreEqual(15000,m.ElapsedMs);Assert.AreEqual(10000,m.HeadFrontArcMm);Assert.AreEqual(0,m.ObservedCrossings().Count);}
  [Test] public void FailedLargeAdvancePublishesNoPartialState(){var m=Create();var before=m.CaptureLocal();Assert.Throws<InvalidOperationException>(()=>m.Advance(100000));Assert.IsTrue(JToken.DeepEquals(before,m.CaptureLocal()));}
  [Test] public void RestoreDuringRampReplaysOriginalDefinitionAndPendingTarget(){var m=Create(first:Sample(0));m.SetTargetSpeed(10000);m.SelectPath("RIGHT");m.Advance(137);var saved=m.CaptureLocal();var r=RailConsistMotion.RestoreLocal(saved,()=>Create(first:Sample(0)));m.Advance(2400);r.Advance(2400);Assert.IsTrue(JToken.DeepEquals(m.CaptureLocal(),r.CaptureLocal()));saved["sample"]["headDistanceMm"]=99999;Assert.Throws<ArgumentException>(()=>RailConsistMotion.RestoreLocal(saved,()=>Create(first:Sample(0))));}
  [Test] public void OriginalConfigurationAndReturnedDataAreIsolated(){var p=Profile();var m=Create(p);p["paths"]["RIGHT"]["points"][2]["yMm"]=999;var s=m.ReadSample();s["actualMmPerSecond"]=0;m.SelectPath("RIGHT");m.Advance(4500);Assert.AreEqual(10000,m.ActualSpeedMmPerSecond);Assert.Greater(m.Occupancy()[0].Front.DriverRightMm,0);var e=m.ObservedCrossings();e.Clear();Assert.AreEqual(2,m.ObservedCrossings().Count);}
  [Test] public void OccupiedBodyIncludesVerticesInsideBend(){var m=Create();m.SelectPath("RIGHT");m.Advance(4500);Assert.AreEqual(3,m.Occupancy()[0].Centerline.Count);}
  [Test] public void SixCarMaximumKeepsRearOnApproachWhenHeadEscapes(){var p=Profile();LongConsist(p);var m=Create(p,Sample(10000,35000));m.SelectPath("RIGHT");m.Advance(2000);Assert.Greater(m.Occupancy()[0].Front.DriverRightMm,0);Assert.AreEqual(0,m.Occupancy().Last().Rear.DriverRightMm);Assert.IsFalse(m.TailPassedSplit);}
  [TestCase("arc")][TestCase("prefix")][TestCase("gap")][TestCase("count")][TestCase("duplicate")]
  public void InvalidProfileIsRejectedAtBoundary(string kind){var p=Profile();if(kind=="arc")p["paths"]["RIGHT"]["points"][2]["sMm"]=51000;if(kind=="prefix")p["paths"]["RIGHT"]["points"][0]["xMm"]=-39999;if(kind=="gap")p["vehicles"][1]["gapAfterMm"]=1;if(kind=="count")p["maxVehicles"]=1;if(kind=="duplicate")p["vehicles"][1]["id"]="loco";Assert.Throws<ArgumentException>(()=>Create(p));}
  [TestCase("null")][TestCase("empty")][TestCase("reversed")][TestCase("extra")][TestCase("time")]
  public void InvalidAttackMetadataCannotEnterOriginalProfile(string kind){var p=Profile();if(kind=="null")p["attack"]=JValue.CreateNull();if(kind=="empty")p["attack"]["areas"]=new JArray();if(kind=="reversed")p["attack"]["areas"][0]["maxXmm"]=-1;if(kind=="extra")p["attack"]["invented"]=1;if(kind=="time")p["attack"]["impactAtMs"]=-1;Assert.Throws<ArgumentException>(()=>Create(p));}
  [Test] public void TotalSampleBudgetRejectsWithoutPartialPublication(){var m=Create(first:Sample(0));m.Advance(36000000);var before=m.CaptureLocal();Assert.Throws<InvalidOperationException>(()=>m.Advance(1));Assert.IsTrue(JToken.DeepEquals(before,m.CaptureLocal()));}
  [Test] public void EmitSourceContractTracesForAuthorityComparison(){var traces=new JArray();foreach(string kind in new[]{"ENTRY","LEFT","RIGHT","LONG_DEFECT","WIDE_SLOW","WIDE_FAST","STOP","RAMP"}){var p=Profile();var first=Sample();long duration=5500;if(kind=="LONG_DEFECT"){LongConsist(p);first=Sample(10000,35000);p["attack"]["impactAtMs"]=12000;duration=2000;}if(kind.StartsWith("WIDE")){p=WideProfile();first=Sample(kind=="WIDE_FAST"?20000:10000,60000);duration=15000;}if(kind=="STOP"||kind=="RAMP")first=Sample(0);var m=Create(p,first);if(kind!="ENTRY")m.SelectPath(kind=="LEFT"?"LEFT":"RIGHT");if(kind=="RAMP")m.SetTargetSpeed(10000);var samples=new JArray(m.Advance(duration));CheckSamples(first,samples,10000);traces.Add(new JObject{["name"]=kind,["profile"]=p,["initial"]=first,["selectedRoute"]=m.SelectedPath,["samples"]=samples,["events"]=m.ObservedCrossings(),["head"]=m.HeadFrontArcMm,["rear"]=m.TailRearArcMm,["nextBranchAllowed"]=m.NextBranchPermitted});}Directory.CreateDirectory("D:/Project/LASTRAIL/QA/WorldBossRail-20261002/Motion");File.WriteAllText("D:/Project/LASTRAIL/QA/WorldBossRail-20261002/Motion/unity-traces.json",new JObject{["status"]="LOCAL_TEST_PROFILE",["cases"]=traces}.ToString());Assert.AreEqual(8,traces.Count);}
  static JObject WideProfile(){var p=Profile();LongConsist(p);for(int i=0;i<6;i++)p["vehicles"][i]["lengthMm"]=i==5?10000:9000;p["geometryRef"]="LOCAL_WIDE_TRIAL";p["attack"]["impactAtMs"]=25000;p["attack"]["areas"][0]["maxXmm"]=390000;p["paths"]["LEFT"]=Path(100000,500000,new long[][]{new[]{0L,-100000,0},new[]{100000L,0,0},new[]{500000L,400000,0},new[]{700000L,600000,0}});p["paths"]["RIGHT"]=Path(100000,505612,new long[][]{new[]{0L,-100000,0},new[]{100000L,0,0},new[]{120000L,20000,0},new[]{132806L,30000,8000},new[]{472806L,370000,8000},new[]{485612L,380000,0},new[]{505612L,400000,0},new[]{705612L,600000,0}});return p;}
  static JObject Path(long split,long merge,long[][] points)=>new JObject{["splitSmm"]=split,["mergeSmm"]=merge,["points"]=new JArray(points.Select(v=>new JObject{["sMm"]=v[0],["xMm"]=v[1],["yMm"]=v[2]}))};
  static void CheckSamples(JObject initial,JArray samples,long acceleration){var prev=initial;foreach(JObject next in samples){long dt=(long)next["atMs"]-(long)prev["atMs"],num=((long)prev["actualMmPerSecond"]+(long)next["actualMmPerSecond"])*dt+(long)prev["distanceRemainder2000"];Assert.AreEqual((long)prev["headDistanceMm"]+num/2000,(long)next["headDistanceMm"]);Assert.AreEqual(num%2000,(long)next["distanceRemainder2000"]);Assert.LessOrEqual(Math.Abs((long)next["actualMmPerSecond"]-(long)prev["actualMmPerSecond"])*1000,acceleration*dt);Assert.LessOrEqual(dt,1000);Assert.Greater(dt,0);prev=next;}}
 }
}
#endif


